using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
namespace kok {
 public class Operation {public string id,module,source,title,created,state="proposed",undoneBy,createdItemId,createdStamp,fileVersion;public bool reviewOperation=true;public List<AgentChange> patches=new List<AgentChange>();public List<ResourcePatch> resources=new List<ResourcePatch>();}
 public sealed class Operations {
  readonly Library library;readonly Action<string,object> notify;
  public Operations(Library library,Action<string,object> notify){this.library=library;this.notify=notify??((n,v)=>{});}
  public List<Operation> List(){return library.OperationList();}
  public Operation Propose(string title,string module,string source,List<AgentChange> patches,string id=null){return library.OperationPropose(title,module,source,patches,id);}
  public Operation Apply(string id,bool agentApproval=false){var op=library.OperationApply(id,agentApproval);notify("op.applied",new{id=op.id,module=op.module,source=op.source});notify("libraryChanged",null);return op;}
  public Operation Undo(string id){var op=library.OperationUndo(id);notify("op.undone",new{id=op.id,module=op.module,source=op.source});notify("libraryChanged",null);return op;}
  public Operation Skip(string id){return library.OperationSkip(id);}
  public Operation Created(string id,string task,string module,Entry entry){return library.OperationCreated(id,"agent:"+task,module,entry);}
 }
 public partial class Library {
  List<Operation> OperationRows {get{if(Db.operations==null)Db.operations=new List<Operation>();return Db.operations;}}
  public List<Operation> OperationList(int offset=0,int limit=100){lock(gate)return store.OperationPage(offset,limit);}
  Operation FindOperation(string id){var op=OperationRows.FirstOrDefault(o=>o.id==id);if(op!=null)return op;op=store.Operation(id);if(op!=null)OperationRows.Add(op);return op;}
  public string OperationStatus(string id){lock(gate){var op=FindOperation(id);return op==null?"":op.state;}}
  public Operation OperationSkip(string id){lock(gate){var op=FindOperation(id);if(op==null||op.source.StartsWith("agent:")||op.state!="proposed")throw new InvalidDataException("操作记录无效。");op.state="skipped";try{Save(false,op.patches.Select(p=>p.id),new[]{op.id});}catch{op.state="proposed";throw;}return Json.Deserialize<Operation>(Json.Serialize(op));}}
  internal Operation TrackCreatedOperation(Entry entry,string id,string source,string module){if(!AgentJournal.ValidId(id)||OperationRows.Any(o=>o.id==id))throw new InvalidDataException("操作记录无效。");source=OperationOrigin.Source??source;var op=new Operation{id=id,module=module,source=source,title=entry.name,created=DateTime.UtcNow.ToString("o"),state="applied",createdItemId=entry.id,createdStamp=AgentCreatedStamp(entry.id)};CheckOpCapacity(op);OperationRows.Add(op);return op;}
  object OpValue(Entry e,string key){return typeof(Entry).GetField(key).GetValue(e);}
  void OpAssign(Entry e,string key,object value){var f=typeof(Entry).GetField(key);f.SetValue(e,Json.Deserialize(Json.Serialize(value),f.FieldType));if(key=="collection"&&!String.IsNullOrEmpty(e.collection)&&!Db.collections.Contains(e.collection))Db.collections.Add(e.collection);}
  void CheckOpPatches(List<AgentChange> changes){
   if(changes==null||changes.Count<1||changes.Count>1000||changes.Any(c=>c==null)||changes.Select(c=>c.id).Distinct().Count()!=changes.Count)throw new InvalidDataException("操作记录无效。");
   var collections=Db.collections.ToList();try{foreach(var c in changes){if(Find(c.id)==null||c.before==null||c.after==null||c.after.Count<1||c.after.Count>30||!c.before.Keys.OrderBy(x=>x).SequenceEqual(c.after.Keys.OrderBy(x=>x))||c.after.Keys.Any(k=>ModuleRegistry.Builtins.FieldOwner(k)==null&& !new[]{"aiCategory","aiSummary","aiFingerprint"}.Contains(k)))throw new InvalidDataException("操作记录无效。");var candidate=Json.Deserialize<Entry>(Json.Serialize(Find(c.id)));var regular=c.after.Where(p=>!new[]{"aiCategory","aiSummary","aiFingerprint"}.Contains(p.Key)).ToDictionary(p=>p.Key,p=>p.Value);ValidateAndAssign(candidate,regular);foreach(var pair in c.after.Where(p=>new[]{"aiCategory","aiSummary","aiFingerprint"}.Contains(p.Key)))if(!(pair.Value is string)||((string)pair.Value).Length>400)throw new InvalidDataException("操作记录无效。");}}finally{Db.collections=collections;}
  }
  void CheckOpCapacity(Operation added){if(Json.Serialize(added).Length>8*1024*1024)throw new InvalidDataException("操作历史空间不足，记录已保留，未执行新修改。");}
  public Operation OperationPropose(string title,string module,string source,List<AgentChange> patches,string id=null){lock(gate){CheckOpPatches(patches);id=id??OperationOrigin.Id??Guid.NewGuid().ToString("N");source=OperationOrigin.Source??source;var previous=FindOperation(id);if(previous!=null)return Json.Deserialize<Operation>(Json.Serialize(previous));if(!AgentJournal.ValidId(id)||String.IsNullOrWhiteSpace(source)||source.Length>80)throw new InvalidDataException("操作记录无效。");var op=new Operation{id=id,module=module,source=source,title=title,created=DateTime.UtcNow.ToString("o"),patches=Json.Deserialize<List<AgentChange>>(Json.Serialize(patches))};CheckOpCapacity(op);OperationRows.Add(op);try{Save(false,op.patches.Select(p=>p.id),new[]{op.id});}catch{OperationRows.Remove(op);throw;}return Json.Deserialize<Operation>(Json.Serialize(op));}}
  public Operation OperationApply(string id,bool agentApproval=false){lock(gate){var op=FindOperation(id);if(op==null)throw new InvalidDataException("操作记录无效。");if(op.source.StartsWith("agent:",StringComparison.Ordinal)&&!agentApproval)throw new InvalidOperationException("请在 Agent 任务中确认这项修改。");if(op.state=="applied")return Json.Deserialize<Operation>(Json.Serialize(op));if(op.state!="proposed")throw new InvalidDataException("操作记录无效。");if(op.resources!=null&&op.resources.Count>0)return ApplyResources(op,false);CheckOpPatches(op.patches);foreach(var c in op.patches)foreach(var p in c.before)if(Json.Serialize(OpValue(Find(c.id),p.Key))!=Json.Serialize(p.Value))throw new InvalidOperationException("内容已被修改，已保留当前内容。请重新查看后再操作。");
    var collections=Db.collections.ToList();try{foreach(var c in op.patches)foreach(var p in c.after)OpAssign(Find(c.id),p.Key,p.Value);op.state="applied";Save(false,op.patches.Select(p=>p.id),new[]{op.id});}catch{foreach(var c in op.patches)foreach(var p in c.before)OpAssign(Find(c.id),p.Key,p.Value);Db.collections=collections;op.state="proposed";throw;}return Json.Deserialize<Operation>(Json.Serialize(op));}}
  public Operation OperationUndo(string id){lock(gate){var op=FindOperation(id);if(op==null||op.state!="applied")throw new InvalidDataException("操作记录无效。");if(op.resources!=null&&op.resources.Count>0)return ApplyResources(op,true);if(op.createdItemId!=null){if(AgentCreatedStamp(op.createdItemId)!=op.createdStamp)throw new InvalidOperationException("内容已被修改，已保留当前内容。请重新查看后再操作。");var item=Find(op.createdItemId);Db.items.Remove(item);op.state="undone";op.undoneBy=Guid.NewGuid().ToString("N");try{Save(false,new[]{op.createdItemId},new[]{op.id});}catch{Db.items.Add(item);op.state="applied";op.undoneBy=null;throw;}return Json.Deserialize<Operation>(Json.Serialize(op));}
    foreach(var c in op.patches)foreach(var p in c.after)if(Find(c.id)==null||Json.Serialize(OpValue(Find(c.id),p.Key))!=Json.Serialize(p.Value))throw new InvalidOperationException("内容已被修改，已保留当前内容。请重新查看后再操作。");using(var file=RestoreFile(op)){var collections=Db.collections.ToList();try{foreach(var c in op.patches)foreach(var p in c.before)OpAssign(Find(c.id),p.Key,p.Value);op.state="undone";op.undoneBy=Guid.NewGuid().ToString("N");Save(false,op.patches.Select(p=>p.id),new[]{op.id});if(file!=null)file.Commit();}catch{foreach(var c in op.patches)foreach(var p in c.after)OpAssign(Find(c.id),p.Key,p.Value);Db.collections=collections;op.state="applied";op.undoneBy=null;throw;}return Json.Deserialize<Operation>(Json.Serialize(op));}}}
  public Operation OperationCreated(string id,string source,string module,Entry entry){lock(gate){var old=FindOperation(id);if(old!=null)return Json.Deserialize<Operation>(Json.Serialize(old));var op=new Operation{id=id,module=module,source=source,title=entry.name,created=DateTime.UtcNow.ToString("o"),state="applied",createdItemId=entry.id,createdStamp=AgentCreatedStamp(entry.id)};CheckOpCapacity(op);OperationRows.Add(op);try{Save(false,op.patches.Select(p=>p.id),new[]{op.id});}catch{OperationRows.Remove(op);throw;}return Json.Deserialize<Operation>(Json.Serialize(op));}}
  public Operation ProposeBulkCollection(List<string> ids,string collection){lock(gate){if(ids==null||ids.Count==0||ids.Count>1000||ids.Distinct().Count()!=ids.Count||ids.Any(id=>Find(id)==null)||String.IsNullOrWhiteSpace(collection)||collection.Length>100||collection.Any(Char.IsControl))throw new InvalidDataException("请选择文件并填写有效分类。");return OperationPropose("移入分类","operations","user",ids.Select(id=>new AgentChange{id=id,before=new Dictionary<string,object>{{"collection",Find(id).collection??""}},after=new Dictionary<string,object>{{"collection",collection.Trim()}}}).ToList());}}
  public Operation ProposeMetadataEdit(string id,string category,List<string> tags,string summary){lock(gate){var e=Find(id);if(e==null)throw new InvalidDataException("资料已移除。");var row=new OrganizeSuggestion{category=(category??"").Trim(),tags=tags,summary=(summary??"").Trim()};ValidateOrganization(row);var before=new Dictionary<string,object>();foreach(var key in new[]{"collection","tags","aiCategory","aiSummary"})before[key]=OpValue(e,key);return OperationPropose("编辑分类与标签","operations","user",new List<AgentChange>{new AgentChange{id=id,before=before,after=new Dictionary<string,object>{{"collection",row.category},{"tags",row.tags},{"aiCategory",row.category},{"aiSummary",row.summary}}}});}}
  public Operation ProposeOrganization(List<OrganizeSuggestion> suggestions,List<string> ids){lock(gate){if(ids==null||ids.Count<1||ids.Count>50||ids.Distinct().Count()!=ids.Count||ids.Any(id=>!suggestions.Any(x=>x.id==id)))throw new InvalidDataException("整理结果已失效，请重新分析。");var rows=suggestions.Where(s=>ids.Contains(s.id)).ToList();foreach(var row in rows){if(Find(row.id)==null||OrganizeFingerprint(Find(row.id),row.content)!=row.fingerprint)throw new InvalidDataException("文件已变化，请重新分析后应用。");ValidateOrganization(row);}var changes=rows.Select(row=>{var e=Find(row.id);var before=new Dictionary<string,object>();foreach(var key in new[]{"collection","tags","aiCategory","aiSummary","aiFingerprint"})before[key]=OpValue(e,key);return new AgentChange{id=e.id,before=before,after=new Dictionary<string,object>{{"collection",row.category},{"tags",row.tags},{"aiCategory",row.category},{"aiSummary",row.summary},{"aiFingerprint",row.fingerprint}}};}).ToList();return OperationPropose("应用整理建议","operations","batch",changes);}}
 }
}
